// Generated by tools/make_panel.py from the landing page. Edit there (or the runtime JS) and re-run.
enum PanelHTML {
    /// Every pop-up style: (key, "walk" or "world", display name).
    static let styles: [(key: String, group: String, name: String)] = [
        ("classic", "walk", "Classic"),
        ("kitty", "walk", "Kitty"),
        ("pup", "walk", "Pup"),
        ("panda", "walk", "Panda"),
        ("fox", "walk", "Fox"),
        ("bunny", "walk", "Bunny"),
        ("dino", "walk", "Dino"),
        ("robo", "walk", "Robo"),
        ("blobby", "walk", "Blobby"),
        ("aquarium", "world", "Aquarium"),
        ("galaxy", "world", "Galaxy"),
        ("synth", "world", "Neon Drive"),
        ("sakura", "world", "Sakura"),
        ("fireflies", "world", "Firefly Night"),
        ("code", "world", "Code Rain"),
        ("aurora", "world", "Aurora"),
        ("snow", "world", "Snow Day"),
        ("lofi", "world", "Lo-fi Rain"),
        ("dragon", "world", "Dragon Lair"),
        ("candy", "world", "Cloud Nine"),
    ]

    static func page(mode: String, buddy: String) -> String {
        template.replacingOccurrences(of: "__MODE__", with: mode).replacingOccurrences(of: "__BUDDY__", with: buddy)
    }

    static let template = #"""
<!doctype html><html><head><meta charset="utf-8"><style>
#fc-lp .panel{--pbg:#16161C;--ptext:#fff;--psub:#D9DAE6;--pfaint:#A9ADC4;--pacc:#8B74FF;--pkbd:#22222C;--pline:#555566;--pborder:rgba(255,255,255,.07);--pok:#4ADE80;--pcheck:#16161C;position:absolute;right:0;bottom:0;width:340px;background:var(--pbg);color:var(--ptext);border-radius:18px;padding:18px;box-shadow:0 30px 60px -20px rgba(10,8,30,.55);border:1.5px solid var(--pborder);z-index:4;transition:background .4s,color .4s,border-color .4s}
#fc-lp .p-head{display:flex;align-items:center;gap:10px;font-weight:600;font-size:15px}
#fc-lp .p-dot{width:10px;height:10px;border-radius:50%;background:#FF5A5F;box-shadow:0 0 0 4px rgba(255,90,95,.25)}
#fc-lp .p-dot.work{background:var(--pacc);box-shadow:0 0 0 4px color-mix(in srgb,var(--pacc) 25%,transparent)}
#fc-lp .p-dot.ok{background:var(--pok);box-shadow:0 0 0 4px color-mix(in srgb,var(--pok) 25%,transparent)}
#fc-lp .wave{display:flex;align-items:center;gap:3px;height:26px;margin:12px 0 8px}
#fc-lp .wave b{width:4px;border-radius:3px;background:var(--pacc);display:block;height:6px;transition:height .12s}
#fc-lp .said{font-size:15px;color:var(--psub);min-height:44px}
#fc-lp .said:after{content:'';display:inline-block;width:2px;height:16px;background:#8B74FF;margin-left:2px;vertical-align:-2px;animation:fcblink 1s steps(1) infinite;background:var(--pacc)}
#fc-lp .said.nocaret:after{display:none}
#fc-lp .steps{list-style:none;margin-top:12px;display:grid;gap:8px}
#fc-lp .steps li{display:flex;align-items:center;gap:10px;font-size:14px;color:var(--psub);opacity:0;transform:translateY(4px);transition:all .3s}
#fc-lp .steps li.show{opacity:1;transform:none}
#fc-lp .steps li s{width:18px;height:18px;border-radius:50%;border:2px solid var(--pline);flex:none;display:grid;place-items:center;text-decoration:none}
#fc-lp .steps li.done s{background:var(--pok);border-color:var(--pok)}
#fc-lp .steps li.done s:after{content:'';width:7px;height:4px;border-left:2px solid var(--pcheck);border-bottom:2px solid var(--pcheck);transform:rotate(-45deg) translate(1px,-1px)}
#fc-lp .p-foot{margin-top:12px;font-size:12px;color:var(--pfaint);display:flex;justify-content:space-between}
#fc-lp kbd{font-family:inherit;font-size:12px;background:var(--pkbd);border:1px solid var(--pline);border-radius:6px;padding:1px 6px;color:var(--psub)}

/* ---------- pop-up buddies ---------- */
#fc-lp .panel[data-buddy=kitty]{--pbg:#FFF3F8;--ptext:#4A2236;--psub:#6B3D55;--pfaint:#A57790;--pacc:#FF6FA8;--pkbd:#FFE1EE;--pline:#F3C3D8;--pborder:#FFC2DA;--pok:#FF6FA8;--pcheck:#fff;box-shadow:0 30px 60px -24px rgba(255,111,168,.55)}
#fc-lp .panel[data-buddy=pup]{--pbg:#FFF8EE;--ptext:#3B2716;--psub:#6A4A2E;--pfaint:#A88663;--pacc:#FF9A3D;--pkbd:#FFE9CC;--pline:#EFCFA8;--pborder:#FFD9AE;--pok:#3FBF6B;--pcheck:#fff;box-shadow:0 30px 60px -24px rgba(255,154,61,.5)}
#fc-lp .panel[data-buddy=robo]{--pbg:#0A1420;--ptext:#E6FBFF;--psub:#A8D8E0;--pfaint:#5F8A94;--pacc:#2FF3E0;--pkbd:#12263A;--pline:#24435A;--pborder:#1F4B63;--pok:#2FF3E0;--pcheck:#0A1420;box-shadow:0 30px 60px -20px rgba(47,243,224,.35)}
#fc-lp .panel[data-buddy=robo] .p-head{font-family:ui-monospace,'SF Mono',Menlo,monospace;letter-spacing:-.02em}
#fc-lp .panel[data-buddy=blobby]{--pbg:#EEFDF5;--ptext:#123B2A;--psub:#2F6650;--pfaint:#6FA48C;--pacc:#22C38E;--pkbd:#D3F7E6;--pline:#B5E8D1;--pborder:#AEEBD0;--pok:#22C38E;--pcheck:#fff;box-shadow:0 30px 60px -24px rgba(34,195,142,.45)}
#fc-lp .track{position:absolute;left:14px;right:14px;top:-40px;height:44px;pointer-events:none}
#fc-lp .buddy{position:absolute;bottom:0;left:0;width:56px;height:44px;pointer-events:auto;cursor:pointer;animation:fcwalk 14s linear infinite}
#fc-lp .buddy .flip{width:100%;height:100%;animation:fcflip 14s steps(1) infinite}
#fc-lp .buddy .bob{width:100%;height:100%;animation:fcbob .38s ease-in-out infinite alternate}
#fc-lp .buddy svg{width:56px;height:44px;display:block;overflow:visible}
#fc-lp .buddy .leg{transform-box:fill-box;transform-origin:50% 0;animation:fcleg .38s ease-in-out infinite alternate}
#fc-lp .buddy .leg.l2{animation-delay:-.38s}
#fc-lp .buddy .tail{transform-box:fill-box;transform-origin:100% 100%;animation:fcwag .45s ease-in-out infinite alternate}
#fc-lp .buddy .eyes{transform-box:fill-box;transform-origin:50% 50%;animation:fceye 4.2s infinite}
#fc-lp .buddy .head{transform-box:fill-box;transform-origin:50% 80%}
#fc-lp .buddy .glow{animation:fcglow 1.1s ease-in-out infinite alternate}
#fc-lp .buddy .squish{transform-box:fill-box;transform-origin:50% 100%;animation:fcsquish .45s ease-in-out infinite alternate}
#fc-lp .panel.is-listen .buddy,#fc-lp .panel.is-listen .buddy .flip{animation-play-state:paused}
#fc-lp .panel.is-listen .buddy .leg,#fc-lp .panel.is-listen .buddy .bob{animation-play-state:paused}
#fc-lp .panel.is-listen .buddy .head{animation:fctilt .9s ease-in-out infinite alternate}
#fc-lp .panel.is-work .buddy .leg,#fc-lp .panel.is-work .buddy .bob,#fc-lp .panel.is-work .buddy .squish{animation-duration:.22s}
#fc-lp .buddy.hop .bob{animation:fchop .55s cubic-bezier(.3,1.6,.5,1) 1}
#fc-lp .spark{position:absolute;bottom:30px;font-size:15px;line-height:1;color:var(--pacc);pointer-events:none;animation:fcspark 1.3s ease-out forwards;font-weight:700}
#fc-lp .say-bubble{position:absolute;bottom:50px;white-space:nowrap;background:var(--pbg);color:var(--ptext);border:1.5px solid var(--pborder);font-size:12px;font-weight:600;padding:6px 10px;border-radius:12px;box-shadow:0 8px 20px -8px rgba(0,0,0,.35);animation:fcpop 2.4s ease forwards;pointer-events:none}
@keyframes fcwalk{0%{left:0}50%{left:calc(100% - 56px)}100%{left:0}}
@keyframes fcflip{0%{transform:scaleX(1)}50%{transform:scaleX(-1)}}
@keyframes fcbob{from{transform:translateY(0)}to{transform:translateY(-1.6px)}}
@keyframes fcleg{from{transform:rotate(20deg)}to{transform:rotate(-20deg)}}
@keyframes fcwag{from{transform:rotate(-12deg)}to{transform:rotate(14deg)}}
@keyframes fceye{0%,90%,100%{transform:scaleY(1)}94%{transform:scaleY(.1)}}
@keyframes fctilt{from{transform:rotate(-7deg)}to{transform:rotate(7deg)}}
@keyframes fcglow{from{opacity:.35}to{opacity:1}}
@keyframes fcsquish{from{transform:scale(1.07,.9)}to{transform:scale(.96,1.05) translateY(-3px)}}
@keyframes fchop{0%{transform:translateY(0)}45%{transform:translateY(-16px)}100%{transform:translateY(0)}}
@keyframes fcspark{0%{opacity:0;transform:translate(0,0) scale(.6)}20%{opacity:1}100%{opacity:0;transform:translate(var(--dx),-46px) scale(1.15)}}
@keyframes fcpop{0%{opacity:0;transform:translateY(6px) scale(.9)}12%,82%{opacity:1;transform:translateY(0) scale(1)}100%{opacity:0;transform:translateY(-4px)}}

/* more buddies */
#fc-lp .panel[data-buddy=panda]{--pbg:#F7F7FA;--ptext:#1E1E26;--psub:#4A4A57;--pfaint:#8B8B98;--pacc:#2B2B33;--pkbd:#ECECF2;--pline:#D9D9E2;--pborder:#E1E1E8;--pok:#3FBF6B;--pcheck:#fff;box-shadow:0 30px 60px -24px rgba(30,30,40,.4)}
#fc-lp .panel[data-buddy=fox]{--pbg:#FFF4EA;--ptext:#3A1C08;--psub:#6B3A17;--pfaint:#A9774F;--pacc:#FF7A1A;--pkbd:#FFE3CC;--pline:#F3C9A4;--pborder:#FFCFA6;--pok:#FF7A1A;--pcheck:#fff;box-shadow:0 30px 60px -24px rgba(255,122,26,.5)}
#fc-lp .panel[data-buddy=bunny]{--pbg:#F6F1FF;--ptext:#2E2147;--psub:#57487A;--pfaint:#9787B8;--pacc:#A47BFF;--pkbd:#ECE2FF;--pline:#DCCEFA;--pborder:#DCCBFF;--pok:#A47BFF;--pcheck:#fff;box-shadow:0 30px 60px -24px rgba(164,123,255,.5)}
#fc-lp .panel[data-buddy=dino]{--pbg:#F1FBEA;--ptext:#183513;--psub:#3C6634;--pfaint:#7FA676;--pacc:#4FC23F;--pkbd:#DDF5D0;--pline:#C2E8B2;--pborder:#BDEBA9;--pok:#4FC23F;--pcheck:#fff;box-shadow:0 30px 60px -24px rgba(79,194,63,.45)}

/* worlds: a living scene inside the pop-up */
#fc-lp .panel{background:var(--pbgimg,var(--pbg))}
#fc-lp .scene{position:absolute;inset:0;border-radius:inherit;overflow:hidden;pointer-events:none;z-index:0}
#fc-lp .panel > .p-head,#fc-lp .panel > .wave,#fc-lp .panel > .said,#fc-lp .panel > .steps,#fc-lp .panel > .p-foot{position:relative;z-index:1}
#fc-lp .panel.world .p-head,#fc-lp .panel.world .said,#fc-lp .panel.world .steps li,#fc-lp .panel.world .p-foot{text-shadow:0 0 2px var(--pbg),0 1px 10px var(--pbg),0 0 18px var(--pbg)}
#fc-lp .panel.world{min-height:250px}
#fc-lp .panel[data-buddy=synth]{padding-bottom:116px}
#fc-lp .panel[data-buddy=fireflies]{padding-bottom:62px}
#fc-lp .panel[data-buddy=aquarium]{padding-bottom:58px}
#fc-lp .scene .resident{position:absolute;pointer-events:auto;cursor:pointer}
#fc-lp .scene .resident svg{display:block;width:100%;height:auto;overflow:visible}
#fc-lp .resident.hop .ri{animation:fchop .55s cubic-bezier(.3,1.6,.5,1) 1}
#fc-lp .scene .spark{bottom:auto}
#fc-lp .panel[data-buddy=aquarium]{--pbg:#06243D;--pbgimg:linear-gradient(180deg,#0F5283 0%,#083456 55%,#05223A 100%);--ptext:#EAF8FF;--psub:#C4E9FB;--pfaint:#7FB6D3;--pacc:#4FD8FF;--pkbd:#0C3556;--pline:#2A6A92;--pborder:#1F6A95;--pok:#4FD8FF;--pcheck:#06243D;box-shadow:0 30px 60px -20px rgba(79,216,255,.4)}
#fc-lp .panel[data-buddy=galaxy]{--pbg:#0B0824;--pbgimg:radial-gradient(130% 90% at 85% 0%,#41208A 0%,#160C3D 45%,#07051A 100%);--ptext:#F3EEFF;--psub:#CFC3FF;--pfaint:#8A7CC4;--pacc:#C49BFF;--pkbd:#1C1446;--pline:#3B2F78;--pborder:#3A2A80;--pok:#7CF5C8;--pcheck:#0B0824;box-shadow:0 30px 60px -20px rgba(150,100,255,.5)}
#fc-lp .panel[data-buddy=synth]{--pbg:#1B0A2E;--pbgimg:linear-gradient(180deg,#140726 0%,#2E0B45 58%,#4C1158 100%);--ptext:#FFF1FD;--psub:#F6C8F0;--pfaint:#B57FC0;--pacc:#FF4FD8;--pkbd:#2A1043;--pline:#5A2370;--pborder:#7A2A8C;--pok:#2FF3E0;--pcheck:#1B0A2E;box-shadow:0 30px 60px -20px rgba(255,79,216,.5)}
#fc-lp .panel[data-buddy=sakura]{--pbg:#FFF4F8;--pbgimg:linear-gradient(165deg,#FFF8FB 0%,#FFE6F0 100%);--ptext:#4A1F33;--psub:#73405A;--pfaint:#B07A93;--pacc:#FF6F9F;--pkbd:#FFE0EC;--pline:#F5C3D6;--pborder:#FFC7DB;--pok:#FF6F9F;--pcheck:#fff;box-shadow:0 30px 60px -24px rgba(255,111,159,.5)}
#fc-lp .panel[data-buddy=fireflies]{--pbg:#0A1A16;--pbgimg:linear-gradient(180deg,#0B1E2E 0%,#0C2420 70%,#08160F 100%);--ptext:#EFFFF4;--psub:#C4E8D2;--pfaint:#79A88E;--pacc:#D8FF6A;--pkbd:#12302A;--pline:#285046;--pborder:#22503F;--pok:#D8FF6A;--pcheck:#0A1A16;box-shadow:0 30px 60px -20px rgba(216,255,106,.3)}

/* aquarium */
#fc-lp .scene .fish{position:absolute;animation:fcswimL var(--d) linear infinite;animation-delay:var(--dl)}
#fc-lp .scene .fish.rev{animation-name:fcswimR}
#fc-lp .scene .fish.rev svg{transform:scaleX(-1)}
#fc-lp .scene .fish svg{display:block;animation:fcwob 1.4s ease-in-out infinite alternate}
#fc-lp .scene .bub{position:absolute;bottom:-12px;border-radius:50%;border:1.2px solid rgba(190,240,255,.75);background:rgba(190,240,255,.12);animation:fcrise var(--d) ease-in infinite;animation-delay:var(--dl)}
#fc-lp .scene .weed{position:absolute;bottom:-4px;transform-origin:50% 100%;animation:fcsway 3.2s ease-in-out infinite alternate}
#fc-lp .scene .octo{right:12px;bottom:4px;width:50px;animation:fcfloat 2.6s ease-in-out infinite alternate}
#fc-lp .scene .octo .tent{transform-box:fill-box;transform-origin:50% 0;animation:fcsway .9s ease-in-out infinite alternate}
#fc-lp .scene .octo .tent:nth-child(even){animation-delay:-.45s}
#fc-lp .scene.cheer .bub{animation-duration:1.4s}
@keyframes fcswimL{from{left:calc(100% + 10px)}to{left:-60px}}
@keyframes fcswimR{from{left:-60px}to{left:calc(100% + 10px)}}
@keyframes fcwob{from{transform:translateY(-3px)}to{transform:translateY(3px)}}
#fc-lp .scene .fish.rev svg{animation-name:fcwobR}
@keyframes fcwobR{from{transform:scaleX(-1) translateY(-3px)}to{transform:scaleX(-1) translateY(3px)}}
@keyframes fcrise{0%{transform:translate(0,0);opacity:0}10%{opacity:1}100%{transform:translate(var(--dx),-320px);opacity:0}}
@keyframes fcsway{from{transform:rotate(-7deg)}to{transform:rotate(7deg)}}
@keyframes fcfloat{from{transform:translateY(0)}to{transform:translateY(-8px)}}

/* galaxy */
#fc-lp .scene .star{position:absolute;border-radius:50%;background:#fff;animation:fctwinkle var(--d) ease-in-out infinite alternate;animation-delay:var(--dl)}
#fc-lp .scene .planet{position:absolute;right:-14px;top:-16px;width:104px;animation:fcfloat 5s ease-in-out infinite alternate;opacity:.95}
#fc-lp .scene .shoot{position:absolute;width:90px;height:2px;border-radius:2px;background:linear-gradient(90deg,#fff,rgba(255,255,255,0));opacity:0;animation:fcshoot var(--d) ease-in infinite;animation-delay:var(--dl)}
