#fc-lp .scene .astro{left:8%;bottom:16%;width:40px;animation:fcdrift 11s ease-in-out infinite alternate}
@keyframes fctwinkle{from{opacity:.12}to{opacity:1}}
@keyframes fcshoot{0%,80%{opacity:0;transform:translate(0,0) rotate(-28deg)}84%{opacity:1}100%{opacity:0;transform:translate(-170px,92px) rotate(-28deg)}}
@keyframes fcdrift{0%{transform:translate(0,0) rotate(-14deg)}50%{transform:translate(120px,-36px) rotate(12deg)}100%{transform:translate(210px,4px) rotate(-6deg)}}

/* synthwave */
#fc-lp .scene .sunglow{position:absolute;left:calc(50% - 80px);bottom:16px;width:160px;height:160px;border-radius:50%;background:radial-gradient(circle,rgba(255,79,216,.45),rgba(255,79,216,0) 65%);transition:transform .4s}
#fc-lp .scene .sun{position:absolute;left:calc(50% - 40px);bottom:96px;width:80px;height:80px;border-radius:50%;background:linear-gradient(#FFE66D 0%,#FF9A3D 45%,#FF4FD8 100%);-webkit-mask-image:linear-gradient(#000 52%,transparent 52%),repeating-linear-gradient(#000 0 7px,transparent 7px 11px);mask-image:linear-gradient(#000 52%,transparent 52%),repeating-linear-gradient(#000 0 7px,transparent 7px 11px);opacity:.92;transform:translateY(50%);transition:filter .4s}
#fc-lp .scene .horizon{position:absolute;left:0;right:0;bottom:96px;height:2px;background:#FF4FD8;box-shadow:0 0 14px 2px #FF4FD8}
#fc-lp .scene .grid{position:absolute;left:-60%;right:-60%;bottom:0;height:96px;background-image:linear-gradient(rgba(255,79,216,.8) 1.5px,transparent 1.5px),linear-gradient(90deg,rgba(255,79,216,.8) 1.5px,transparent 1.5px);background-size:30px 20px;transform:perspective(110px) rotateX(52deg);transform-origin:50% 100%;animation:fcgrid 1.1s linear infinite;-webkit-mask-image:linear-gradient(transparent,#000 55%);mask-image:linear-gradient(transparent,#000 55%)}
#fc-lp .panel.is-work .scene .grid{animation-duration:.35s}
#fc-lp .scene .car{bottom:93px;left:6%;width:62px;animation:fccar 7s ease-in-out infinite alternate}
#fc-lp .scene.cheer .sun{filter:brightness(1.35) saturate(1.3)}
#fc-lp .scene.cheer .sunglow{transform:scale(1.35)}
@keyframes fcgrid{from{background-position:0 0}to{background-position:0 20px}}
@keyframes fccar{from{left:3%}to{left:76%}}

