#fc-lp .scene .petal{position:absolute;top:-16px;border-radius:80% 0 80% 0;background:linear-gradient(135deg,#FFD3E3,#FF8FB8);animation:fcfall var(--d) linear infinite;animation-delay:var(--dl)}
