@keyframes fcfall{0%{transform:translate(0,0) rotate(0);opacity:0}8%{opacity:1}100%{transform:translate(var(--dx),300px) rotate(560deg);opacity:.25}}
@keyframes fcperch{0%,60%,100%{transform:rotate(0)}70%{transform:rotate(-12deg) translateY(-1px)}80%{transform:rotate(6deg)}}

