#fc-lp .panel[data-buddy=snow]{--pbg:#1C3766;--pbgimg:linear-gradient(180deg,#1A3361 0%,#3D69A6 100%);--ptext:#F4F9FF;--psub:#D6E6FF;--pfaint:#A6C0E6;--pacc:#9FD0FF;--pkbd:#24457A;--pline:#4A72AE;--pborder:#5A86C4;--pok:#9FD0FF;--pcheck:#1C3766;box-shadow:0 30px 60px -20px rgba(120,170,255,.45);padding-bottom:58px}
#fc-lp .panel[data-buddy=lofi]{--pbg:#1E1622;--pbgimg:linear-gradient(180deg,#1A1220 0%,#2B1E2C 100%);--ptext:#FFF4EA;--psub:#EBD3C2;--pfaint:#A88B86;--pacc:#FFB86B;--pkbd:#2E2232;--pline:#4E3A4E;--pborder:#4A3546;--pok:#FFB86B;--pcheck:#1E1622;box-shadow:0 30px 60px -20px rgba(255,184,107,.3);padding-bottom:60px}
#fc-lp .panel[data-buddy=dragon]{--pbg:#200707;--pbgimg:linear-gradient(180deg,#160505 0%,#2E0A08 60%,#4A1206 100%);--ptext:#FFF1E8;--psub:#F5CDB8;--pfaint:#B07A66;--pacc:#FF7A3D;--pkbd:#3A0F0A;--pline:#6A2416;--pborder:#7A2A14;--pok:#FFB347;--pcheck:#200707;box-shadow:0 30px 60px -20px rgba(255,100,40,.45);padding-bottom:40px}
#fc-lp .panel[data-buddy=candy]{--pbg:#FDF1FA;--pbgimg:linear-gradient(170deg,#CDEBFF 0%,#F4E8FF 50%,#FFE3F1 100%);--ptext:#3A2A55;--psub:#5E4A80;--pfaint:#9A88B8;--pacc:#FF7EB6;--pkbd:#FFFFFF;--pline:#E3D3F5;--pborder:#F3D3EA;--pok:#B07CFF;--pcheck:#fff;box-shadow:0 30px 60px -24px rgba(200,140,255,.5);padding-bottom:58px}
#fc-lp .scene .hills{position:absolute;left:0;right:0;bottom:0;width:100%;height:56px}
/* code rain */
#fc-lp .scene .col{position:absolute;top:-70%;font-family:ui-monospace,Menlo,monospace;line-height:1.05;color:#39FF88;text-shadow:0 0 6px rgba(57,255,136,.8);opacity:.4;animation:fccode var(--d) linear infinite;animation-delay:var(--dl);-webkit-mask-image:linear-gradient(transparent,#000 75%);mask-image:linear-gradient(transparent,#000 75%)}
#fc-lp .scene .col b{color:#E6FFEE;font-weight:400}
#fc-lp .scene.cheer .col{opacity:.75}
#fc-lp .scene .bot{right:14px;bottom:10px;width:42px;animation:fcfloat 2.2s ease-in-out infinite alternate}
@keyframes fccode{from{top:-70%}to{top:110%}}
/* aurora */
#fc-lp .scene .ribbon{position:absolute;left:-20%;width:140%;height:64px;border-radius:50%;filter:blur(14px);opacity:.8;animation:fcaurora var(--d) ease-in-out infinite alternate}
#fc-lp .scene.cheer .ribbon{filter:blur(10px) brightness(1.5)}
#fc-lp .scene .bear{right:30px;bottom:22px;width:36px}
#fc-lp .scene .bear .ri{animation:fcperch 3s ease-in-out infinite}
@keyframes fcaurora{0%{transform:translateX(-8%) skewX(-14deg) scaleY(.75)}50%{transform:translateX(4%) skewX(10deg) scaleY(1.25)}100%{transform:translateX(10%) skewX(-6deg) scaleY(.9)}}
/* snow day */
#fc-lp .scene .flake{position:absolute;top:-8px;border-radius:50%;background:#fff;animation:fcsnow var(--d) linear infinite;animation-delay:var(--dl)}
#fc-lp .scene.cheer .flake{animation-duration:2.4s}
#fc-lp .scene .penguin{bottom:10px;left:6%;width:28px;animation:fcwalkp 10s ease-in-out infinite alternate}
#fc-lp .scene .penguin .ri{transform-origin:50% 100%;animation:fcwaddle .32s ease-in-out infinite alternate}
@keyframes fcsnow{0%{transform:translate(0,0)}25%{transform:translate(var(--dx),75px)}50%{transform:translate(0,150px)}75%{transform:translate(var(--dx),225px)}100%{transform:translate(0,310px)}}
@keyframes fcwalkp{from{left:6%}to{left:80%}}
@keyframes fcwaddle{from{transform:rotate(-8deg)}to{transform:rotate(8deg)}}
/* lo-fi rain */
#fc-lp .scene .drop{position:absolute;top:-30px;width:1.2px;height:var(--h);background:linear-gradient(transparent,rgba(210,215,255,.6));animation:fcrain var(--d) linear infinite;animation-delay:var(--dl)}
#fc-lp .scene .city{position:absolute;left:0;right:0;bottom:0;width:100%;height:54px}
#fc-lp .scene .mug{right:16px;bottom:8px;width:38px}
#fc-lp .scene .mug .steam{transform-box:fill-box;animation:fcsteam 2.4s ease-in infinite;opacity:0}
#fc-lp .scene .mug .steam.s2{animation-delay:.8s}
#fc-lp .scene .mug .steam.s3{animation-delay:1.6s}
#fc-lp .scene.cheer .drop{animation-duration:.35s}
@keyframes fcrain{from{transform:translate(0,0) rotate(12deg)}to{transform:translate(-70px,330px) rotate(12deg)}}
@keyframes fcsteam{0%{opacity:0;transform:translateY(4px)}30%{opacity:.9}100%{opacity:0;transform:translateY(-8px)}}
/* dragon lair */
#fc-lp .scene .lava{position:absolute;left:0;right:0;bottom:0;height:90px;background:radial-gradient(120% 100% at 50% 100%,rgba(255,90,20,.6),rgba(255,90,20,0) 70%);animation:fcglow 2s ease-in-out infinite alternate}
#fc-lp .scene .ember{position:absolute;bottom:-6px;border-radius:50%;background:#FFB347;box-shadow:0 0 8px 2px rgba(255,120,40,.85);animation:fcrise var(--d) ease-out infinite;animation-delay:var(--dl)}
#fc-lp .scene .dragon{left:8%;top:40%;width:58px;animation:fcfly 10s ease-in-out infinite alternate}
#fc-lp .scene .dragon .wing{transform-box:fill-box;transform-origin:50% 100%;animation:fcflap .32s ease-in-out infinite alternate}
#fc-lp .scene .dragon .w2{animation-delay:-.16s}
#fc-lp .scene .dragon .fire{opacity:0;transform-box:fill-box;transform-origin:0 50%}
#fc-lp .scene.cheer .dragon .fire{animation:fcfire .2s ease-in-out 8 alternate}
@keyframes fcfly{0%{transform:translate(0,0)}25%{transform:translate(70px,-26px)}50%{transform:translate(150px,6px)}75%{transform:translate(90px,26px)}100%{transform:translate(170px,-14px)}}
@keyframes fcflap{from{transform:scaleY(1)}to{transform:scaleY(.35)}}
@keyframes fcfire{from{opacity:.6;transform:scaleX(.6)}to{opacity:1;transform:scaleX(1.15)}}
/* cloud nine */
#fc-lp .scene .rainbow{position:absolute;right:-20px;top:-6px;width:170px}
#fc-lp .scene .cloud{position:absolute;animation:fcswimR var(--d) linear infinite;animation-delay:var(--dl)}
#fc-lp .scene .twinkle{position:absolute;font-style:normal;font-size:10px;color:#FF9ECF;animation:fctwinkle var(--d) ease-in-out infinite alternate;animation-delay:var(--dl)}
#fc-lp .scene .unicorn{right:14px;bottom:4px;width:52px;animation:fcfloat 2.4s ease-in-out infinite alternate}
#fc-lp .scene.cheer .twinkle{color:#B07CFF;transform:scale(1.6)}

/* picker with tabs */
#fc-lp .picker-top{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;flex-wrap:wrap}
#fc-lp .ptabs{display:inline-flex;background:var(--soft);border:1px solid var(--line);border-radius:11px;padding:3px}
#fc-lp .ptabs button{border:0;background:transparent;font-family:inherit;font-size:13px;font-weight:600;color:var(--muted);padding:6px 12px;border-radius:8px;cursor:pointer}
#fc-lp .ptabs button.on{background:#fff;color:var(--ink);box-shadow:0 1px 3px rgba(0,0,0,.08)}
#fc-lp .ptabs button small{font-size:11px;color:var(--violet);margin-left:3px}
#fc-lp .bchip[hidden]{display:none}
#fc-lp .bchip .wtile{width:30px;height:24px;border-radius:7px;display:grid;place-items:center;overflow:hidden}
#fc-lp .bchip .wtile svg{width:20px;height:20px}
#fc-lp .share{display:inline-flex;align-items:center;gap:8px;font-size:13px;color:var(--muted);padding:8px 12px;border-radius:10px;background:linear-gradient(90deg,#FFF0F7,#F1EDFF);border:1px solid #F0DDF0}
#fc-lp .share b{color:var(--violet-ink)}
#fc-lp .share:hover{border-color:#E2C7EA}

/* buddy picker */
#fc-lp .demo-col{display:flex;flex-direction:column;gap:18px}
#fc-lp .picker{display:flex;flex-direction:column;gap:12px;align-items:stretch}
#fc-lp .picker-label{font-size:13px;font-weight:600;color:var(--faint);display:flex;gap:8px;align-items:center}
#fc-lp .picker-label em{font-style:normal;font-size:11px;font-weight:700;color:var(--violet-ink);background:var(--violet-soft);border-radius:99px;padding:2px 8px}
#fc-lp .bchips{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-start;min-height:88px;align-content:flex-start}
#fc-lp .bchip{display:inline-flex;align-items:center;gap:7px;height:40px;padding:0 12px 0 8px;border-radius:12px;border:1.5px solid var(--line);background:#fff;font-family:inherit;font-size:14px;font-weight:600;color:var(--ink);cursor:pointer;transition:all .18s}
#fc-lp .bchip:hover{transform:translateY(-1px);border-color:#CFC6FF}
#fc-lp .bchip.on{border-color:var(--violet);background:var(--violet-soft);color:var(--violet-ink)}
#fc-lp .bchip .mini{width:28px;height:24px;display:grid;place-items:center}
#fc-lp .bchip .mini svg{width:28px;height:22px;overflow:visible}
#fc-lp .bchip .mini *{animation:none!important}
@keyframes fcblink{50%{opacity:0}}

html,body{margin:0;padding:0;background:transparent;overflow:hidden;-webkit-user-select:none;user-select:none;cursor:default}
#fc-lp{--ink:#15151B;--muted:#5A5A66;--faint:#8A8A96;--line:#E7E6EE;--soft:#F6F5FB;--violet:#5B3DF5;--violet-ink:#4527DB;--violet-soft:#EEEAFF;
  font-family:-apple-system,BlinkMacSystemFont,'SF Pro Text','Helvetica Neue',sans-serif;-webkit-font-smoothing:antialiased;font-size:15px;line-height:1.45}
#fc-lp *{box-sizing:border-box;margin:0;padding:0}
#fc-lp .stage{display:inline-block;padding:50px 22px 24px 22px}
#fc-lp .panel{position:relative;right:auto;bottom:auto;width:360px;box-shadow:0 18px 40px -16px rgba(10,8,30,.55)}
#fc-lp .panel > *:not(.scene):not(.track){position:relative;z-index:1}
#fc-lp .p-head{gap:10px}
#fc-lp .p-head #title{flex:1}
#fc-lp .timer{font-size:13px;font-weight:500;color:var(--pfaint);font-variant-numeric:tabular-nums}
#fc-lp .p-dot.fail{background:#F5A524;box-shadow:0 0 0 4px rgba(245,165,36,.25)}
#fc-lp .said{margin-top:4px}
#fc-lp .said.hint{color:var(--pfaint);font-size:13px}
#fc-lp .steps{margin-top:10px}
#fc-lp .steps li.current s{border-color:var(--pacc);border-top-color:transparent;animation:fcspin .8s linear infinite}
#fc-lp .steps li.failed s{background:#FF5A5F;border-color:#FF5A5F}
#fc-lp .qbox{margin-top:10px;font-size:14px;color:var(--psub);padding:10px 12px;border-radius:10px;background:var(--pkbd);border:1px solid var(--pline)}
#fc-lp .status{margin-top:8px;font-size:13px;color:var(--pfaint)}
#fc-lp .result{margin-top:10px;font-size:15px;color:var(--ptext)}
#fc-lp .btns{display:flex;gap:10px;margin-top:14px}
#fc-lp .pbtn{flex:1;height:38px;border-radius:11px;border:0;font-family:inherit;font-size:14px;font-weight:600;cursor:pointer}
#fc-lp .pbtn.primary{background:var(--pacc);color:var(--pcheck)}
#fc-lp .pbtn.stop{background:#FF5A5F;color:#fff}
#fc-lp .pbtn.ghost{background:transparent;color:var(--ptext);border:1.5px solid var(--pline)}
#fc-lp .p-foot{gap:10px}
#fc-lp .picker{display:none}
#fc-lp.preview{padding:0 6px}
#fc-lp.preview .stage{display:flex;justify-content:center;align-items:flex-start;padding:54px 0 0;height:440px}
#fc-lp.preview .picker{display:flex;flex-direction:column;gap:12px;padding:4px 10px 16px}
#fc-lp .picker-top{display:flex;justify-content:space-between;align-items:center}
#fc-lp .picker-label{font-size:13px;font-weight:600;color:var(--faint)}
#fc-lp .bchips{min-height:0}
@keyframes fcspin{to{transform:rotate(360deg)}}
</style></head><body>
